  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Joy and Hope in Hard Places$j$, $j${"prompt": "Paul wrote about joy, peace and hope while he was in prison. Think of a time when something in your life was hard or uncertain. Tell how a truth from Paul's letters in this unit, such as Philippians 4:6 and 7 or 1 Thessalonians 5:16 to 18, could help you stay hopeful. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Joy and Hope in Hard Places$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Ephesians: Grace, Unity and the Armor of God$j$, $j${"questions": [{"q": "Where was Paul when he wrote Ephesians, Philippians, Colossians and Philemon?", "options": ["On a ship at sea", "In prison", "In Corinth", "In Jerusalem"]}, {"q": "According to Ephesians 2:8, by what are we saved through faith?", "options": ["Good works", "Grace", "The law", "Our own goodness"]}, {"q": "What does Ephesians 4:3 tell believers to keep?", "options": ["The law of Moses", "The Sabbath", "A tenth of the harvest", "The unity of the Spirit in the bond of peace"]}, {"q": "According to Ephesians 6:17, what is the sword of the Spirit?", "options": ["The word of God", "Fasting", "Prayer", "The church"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Ephesians: Grace, Unity and the Armor of God$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,0}'::int[], array[$j$These four letters are called the prison letters because Paul wrote them in chains.$j$,$j$Ephesians 2:8 says, For by grace are ye saved through faith.$j$,$j$Paul urged the church to keep the unity of the Spirit in the bond of peace.$j$,$j$The sword of the Spirit is the word of God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Ephesians: Grace, Unity and the Armor of God$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Philippians and Colossians: Joy and Christ Above All$j$, $j${"questions": [{"q": "What city was the first in Europe where Paul started a church?", "options": ["Athens", "Corinth", "Rome", "Philippi"]}, {"q": "According to Philippians 2:8, how far did Jesus humble Himself?", "options": ["He became a king on earth", "He stayed in heaven", "Unto death, even the death of the cross", "He refused the cross"]}, {"q": "What does Philippians 4:6 tell believers to do instead of being careful for anything?", "options": ["Make requests known unto God by prayer with thanksgiving", "Work harder", "Move to a new city", "Wait in silence"]}, {"q": "According to Colossians 1:18, what is Jesus to the church?", "options": ["A teacher only", "The head of the body", "A guest", "A servant"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Philippians and Colossians: Joy and Christ Above All$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,0,1}'::int[], array[$j$Paul started the church at Philippi on his second journey, as Acts 16 records.$j$,$j$Jesus became obedient unto death, even the death of the cross.$j$,$j$Paul taught prayer and thanksgiving instead of worry.$j$,$j$Colossians 1:18 says He is the head of the body, the church.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Philippians and Colossians: Joy and Christ Above All$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: First and Second Thessalonians: The Hope of the Lord's Return$j$, $j${"questions": [{"q": "In what region was the city of Thessalonica?", "options": ["Galilee", "Judea", "Macedonia", "Egypt"]}, {"q": "According to 1 Thessalonians 4:13, why did Paul write about those who are asleep?", "options": ["To ask for an offering", "To teach the law", "To describe a journey", "So that believers would not sorrow as others who have no hope"]}, {"q": "Which of these is one of the short commands in 1 Thessalonians 5:16 to 18?", "options": ["Build a temple", "Travel to Rome", "Pray without ceasing", "Pay your debts"]}, {"q": "What did Paul tell the Thessalonians in 2 Thessalonians 3:13?", "options": ["Leave the city", "Stop meeting together", "Wait without working", "Be not weary in well doing"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: First and Second Thessalonians: The Hope of the Lord's Return$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,3}'::int[], array[$j$Thessalonica was the capital of Macedonia.$j$,$j$Paul wanted the church to have hope about believers who had died.$j$,$j$First Thessalonians 5:17 says, Pray without ceasing.$j$,$j$Paul urged them to keep doing good while they waited for the Lord.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: First and Second Thessalonians: The Hope of the Lord's Return$j$ on conflict (item_id) do nothing;
